# ============================================================================
# Reproducible Execution Script for "{{TITLE}}"
# ============================================================================
# Description: runs the full analysis pipeline sequentially. Every script in
# scripts/ whose name matches NN_*.R is sourced in numeric order, each in its
# own environment: a script reads its inputs from data/ and results/ and
# writes its outputs there, so any of them can also be run on its own.
#
# Generated by intraitR {{INTRAITR_VERSION}} (launch_intrait_analyses()) on {{DATE}}.
# ============================================================================

# 0. Environment ---------------------------------------------------------------
# A renv lockfile is used when present (renv::snapshot() creates one).
if (file.exists("renv.lock") && requireNamespace("renv", quietly = TRUE))
  renv::restore(prompt = FALSE)

# 1. Base path of the project --------------------------------------------------
if (requireNamespace("here", quietly = TRUE)) setwd(here::here())

# 2. Run every numbered script in order ----------------------------------------
script_paths <- sort(list.files("scripts", pattern = "^[0-9]{2}_.*\\.R$", full.names = TRUE))
script_paths <- script_paths[basename(script_paths) != "00_START_GeneralScript.R"]
cat("Scripts to execute :\n", paste(basename(script_paths), collapse = "\n"), "\n\n")

for (script in script_paths) {
  cat("▶ Loading :", basename(script), "...\n")
  tryCatch(
    source(script, local = new.env(parent = globalenv()), echo = FALSE),
    error = function(e) {
      message("❌ Error in ", basename(script), ": ", conditionMessage(e))
      stop("STOP", call. = FALSE)
    }
  )
  cat("✅ Done :", basename(script), "\n\n")
}

# 3. The Methods & Results report ------------------------------------------------
if (requireNamespace("rmarkdown", quietly = TRUE) && rmarkdown::pandoc_available()) {
  rmarkdown::render("manuscript/Methods_Results.Rmd", quiet = TRUE,
                    envir = new.env(parent = globalenv()))
  cat("✅ Report : manuscript/Methods_Results.docx\n")
} else {
  message("rmarkdown/pandoc not available: knit manuscript/Methods_Results.Rmd in RStudio.")
}

cat("All scripts have been run successfully.\n")
